Here is a production-grade, modular, and concurrency-safe **Automated Stock Portfolio Rebalancing Engine** in C# (.NET 8). 

The engine is structured into three highly decoupled subsystems, using asynchronous design, modern concurrent collections, channel-based high-throughput streaming, and mathematically rigorous tax-lot and execution modeling.

### Architectural Overview

```
                      [ External Market Feed ]
                                 │  (Real-Time Ingestion Channel)
                                 ▼
         ┌──────────────────────────────────────────────┐
         │ (1) MARKET DATA FEED SUBSYSTEM               │
         │     - Ingests pricing ticks (Bid/Ask)        │
         │     - Concurrent, thread-safe cache          │
         │     - Decoupled via pub/sub event stream     │
         └───────────────────────┬──────────────────────┘
                                 │
                     Updates     │ Pulls Prices
                     Portfolio   │ & Calculates Drifts
                     Valuation   ▼
         ┌──────────────────────────────────────────────┐
         │ (2) PORTFOLIO OPTIMIZATION CALCULATOR        │
         │     - Computes Drift & Tracking Errors       │
         │     - Evaluates Drift Threshold Triggers     │
         │     - Generates transaction-cost-aware trades│
         └───────────────────────┬──────────────────────┘
                                 │
                                 │ Generates Proposals
                                 ▼
         ┌──────────────────────────────────────────────┐
         │ (3) TRADE EXECUTION SUBSYSTEM                │
         │     - "Sell-First" execution sequence        │
         │     - Tax-Lot relief (FIFO / LIFO / HIFO)   │
         │     - Broker gateway with slippage/fees     │
         └──────────────────────────────────────────────┘
```

---

### Step-by-Step Implementation

Create a single file or a structured C# project with the code below. It contains clean, production-ready interfaces, concurrent states, and an automated execution coordinator.

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;

namespace PortfolioRebalancerEngine
{
    #region DOMAIN MODELS

    public enum TaxLotMethod
    {
        FIFO, // First In, First Out
        LIFO, // Last In, First Out
        HIFO  // Highest In, First Out (Minimizes capital gains tax)
    }

    public enum OrderSide
    {
        Buy,
        Sell
    }

    public enum OrderStatus
    {
        Pending,
        Filled,
        Rejected
    }

    public record MarketTick(string Symbol, decimal Bid, decimal Ask, DateTime Timestamp);

    public record TaxLot(DateTime AcquiredAt, decimal Quantity, decimal PricePerShare)
    {
        // Property to allow tax lot depletion during matching
        public decimal Quantity { get; set; } = Quantity;
    }

    public class Position
    {
        public string Symbol { get; }
        private readonly List<TaxLot> _taxLots = new();
        private readonly object _lock = new();

        public Position(string symbol, IEnumerable<TaxLot> initialLots)
        {
            Symbol = symbol;
            _taxLots.AddRange(initialLots);
        }

        public decimal TotalQuantity
        {
            get
            {
                lock (_lock)
                {
                    return _taxLots.Sum(x => x.Quantity);
                }
            }
        }

        public IReadOnlyList<TaxLot> GetTaxLots()
        {
            lock (_lock)
            {
                return _taxLots.Select(x => new TaxLot(x.AcquiredAt, x.Quantity, x.PricePerShare)).ToList();
            }
        }

        public void AddTaxLot(TaxLot lot)
        {
            lock (_lock)
            {
                _taxLots.Add(lot);
            }
        }

        public List<TaxLot> RelieveLots(decimal quantityToRelieve, TaxLotMethod method)
        {
            lock (_lock)
            {
                if (quantityToRelieve > TotalQuantity)
                {
                    throw new InvalidOperationException($"Insufficient inventory in {Symbol} to relieve {quantityToRelieve} shares.");
                }

                // Sort according to selection strategy
                IOrderedEnumerable<TaxLot> sortedLots = method switch
                {
                    TaxLotMethod.FIFO => _taxLots.OrderBy(l => l.AcquiredAt),
                    TaxLotMethod.LIFO => _taxLots.OrderByDescending(l => l.AcquiredAt),
                    TaxLotMethod.HIFO => _taxLots.OrderByDescending(l => l.PricePerShare),
                    _ => throw new ArgumentOutOfRangeException(nameof(method), method, null)
                };

                var relievedLots = new List<TaxLot>();
                decimal remainingToRelieve = quantityToRelieve;

                foreach (var lot in sortedLots)
                {
                    if (remainingToRelieve <= 0) break;

                    if (lot.Quantity <= remainingToRelieve)
                    {
                        relievedLots.Add(new TaxLot(lot.AcquiredAt, lot.Quantity, lot.PricePerShare));
                        remainingToRelieve -= lot.Quantity;
                        lot.Quantity = 0; // Mark for removal
                    }
                    else
                    {
                        relievedLots.Add(new TaxLot(lot.AcquiredAt, remainingToRelieve, lot.PricePerShare));
                        lot.Quantity -= remainingToRelieve;
                        remainingToRelieve = 0;
                    }
                }

                // Clean up empty lots
                _taxLots.RemoveAll(l => l.Quantity <= 0);

                return relievedLots;
            }
        }
    }

    public class Portfolio
    {
        private readonly ConcurrentDictionary<string, Position> _positions = new(StringComparer.OrdinalIgnoreCase);
        private readonly object _cashLock = new();
        private decimal _cash;

        public string PortfolioId { get; }

        public decimal Cash
        {
            get { lock (_cashLock) return _cash; }
            set { lock (_cashLock) _cash = value; }
        }

        public Portfolio(string portfolioId, decimal initialCash)
        {
            PortfolioId = portfolioId;
            _cash = initialCash;
        }

        public IReadOnlyDictionary<string, Position> Positions => _positions;

        public void UpdatePosition(string symbol, Action<Position> updateAction)
        {
            var position = _positions.GetOrAdd(symbol, sym => new Position(sym, Enumerable.Empty<TaxLot>()));
            updateAction(position);
            if (position.TotalQuantity == 0)
            {
                _positions.TryRemove(symbol, out _);
            }
        }

        public decimal CalculateTotalValue(IMarketDataFeed marketFeed)
        {
            decimal total = Cash;
            foreach (var kvp in _positions)
            {
                var price = marketFeed.GetLatestPrice(kvp.Key)?.Ask ?? 0; // Conservative estimate based on liquidation ask
                total += kvp.Value.TotalQuantity * price;
            }
            return total;
        }
    }

    #endregion

    #region (1) MARKET DATA FEED SUBSYSTEM

    public interface IMarketDataFeed
    {
        event EventHandler<MarketTick>? OnPriceUpdate;
        Task EnqueueTickAsync(MarketTick tick, CancellationToken cancellationToken = default);
        MarketTick? GetLatestPrice(string symbol);
        void StartStreaming(CancellationToken cancellationToken);
    }

    /// <summary>
    /// Thread-safe, high-performance Market Data Feed using System.Threading.Channels 
    /// for low-overhead producer-consumer tick distribution.
    /// </summary>
    public class MarketDataFeed : IMarketDataFeed
    {
        private readonly ConcurrentDictionary<string, MarketTick> _latestTicks = new(StringComparer.OrdinalIgnoreCase);
        private readonly Channel<MarketTick> _tickChannel;

        public event EventHandler<MarketTick>? OnPriceUpdate;

        public MarketDataFeed(int capacity = 10000)
        {
            _tickChannel = Channel.CreateBounded<MarketTick>(new BoundedChannelOptions(capacity)
            {
                SingleWriter = false,
                SingleReader = true,
                FullMode = BoundedChannelFullMode.DropOldest
            });
        }

        public async Task EnqueueTickAsync(MarketTick tick, CancellationToken cancellationToken = default)
        {
            await _tickChannel.Writer.WriteAsync(tick, cancellationToken);
        }

        public MarketTick? GetLatestPrice(string symbol)
        {
            return _latestTicks.TryGetValue(symbol, out var tick) ? tick : null;
        }

        public void StartStreaming(CancellationToken cancellationToken)
        {
            Task.Run(async () =>
            {
                var reader = _tickChannel.Reader;
                while (await reader.WaitToReadAsync(cancellationToken))
                {
                    while (reader.TryRead(out var tick))
                    {
                        _latestTicks[tick.Symbol] = tick;
                        OnPriceUpdate?.Invoke(this, tick);
                    }
                }
            }, cancellationToken);
        }
    }

    #endregion

    #region (2) PORTFOLIO OPTIMIZATION CALCULATOR

    public record TargetAllocation(IReadOnlyDictionary<string, decimal> Weights);

    public record OptimizationParameters(
        decimal DriftThreshold,       // Absolute percentage drift before triggering action (e.g., 0.05 for 5%)
        decimal TransactionFeeFlat,   // Flat fee applied per order
        decimal TransactionFeeRate,   // Percent fee calculated against total trade cost
        decimal MinOrderValue,        // Minimum execution amount to prevent tiny, inefficient trades
        decimal CashReserve           // Minimum target reserve currency balance
    );

    public record TradeProposal(string Symbol, OrderSide Side, decimal Quantity, decimal EstimatedPrice);

    public record RebalancingProposal(
        IReadOnlyList<TradeProposal> Trades, 
        bool Triggered, 
        decimal AggregateDriftBefore, 
        decimal AggregateDriftAfter
    );

    public interface IPortfolioOptimizer
    {
        RebalancingProposal ComputeRebalancing(
            Portfolio portfolio, 
            TargetAllocation target, 
            OptimizationParameters parameters
        );
    }

    /// <summary>
    /// Computes drift thresholds and dynamic weight reallocations while checking cash constraints 
    /// and incorporating execution overhead costs.
    /// </summary>
    public class PortfolioOptimizer : IPortfolioOptimizer
    {
        private readonly IMarketDataFeed _marketFeed;

        public PortfolioOptimizer(IMarketDataFeed marketFeed)
        {
            _marketFeed = marketFeed;
        }

        public RebalancingProposal ComputeRebalancing(
            Portfolio portfolio, 
            TargetAllocation target, 
            OptimizationParameters parameters)
        {
            decimal totalPortfolioValue = portfolio.CalculateTotalValue(_marketFeed);
            if (totalPortfolioValue <= 0)
            {
                return new RebalancingProposal(Array.Empty<TradeProposal>(), false, 0, 0);
            }

            decimal investableCapital = totalPortfolioValue - parameters.CashReserve;
            if (investableCapital <= 0)
            {
                throw new InvalidOperationException("Portfolio value is below the minimum required Cash Reserve threshold.");
            }

            var currentWeights = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase);
            var targetWeights = target.Weights;
            var proposedTrades = new List<TradeProposal>();

            decimal aggregateDriftBefore = 0.0m;
            bool triggerThresholdMet = false;

            // Step 1: Calculate current weights and absolute drift metrics
            var allSymbols = targetWeights.Keys.Union(portfolio.Positions.Keys, StringComparer.OrdinalIgnoreCase).ToList();

            foreach (var symbol in allSymbols)
            {
                var priceTick = _marketFeed.GetLatestPrice(symbol);
                if (priceTick == null) continue; // Skip assets for which we have no pricing updates yet

                decimal midPrice = (priceTick.Bid + priceTick.Ask) / 2.0m;
                decimal qty = portfolio.Positions.TryGetValue(symbol, out var pos) ? pos.TotalQuantity : 0.0m;
                decimal assetValue = qty * midPrice;
                decimal currentWeight = assetValue / totalPortfolioValue;

                currentWeights[symbol] = currentWeight;

                decimal targetWeight = targetWeights.TryGetValue(symbol, out var tw) ? tw : 0.0m;
                decimal drift = Math.Abs(currentWeight - targetWeight);
                aggregateDriftBefore += drift;

                if (drift >= parameters.DriftThreshold)
                {
                    triggerThresholdMet = true;
                }
            }

            if (!triggerThresholdMet)
            {
                return new RebalancingProposal(Array.Empty<TradeProposal>(), false, aggregateDriftBefore, aggregateDriftBefore);
            }

            // Step 2: Compute target quantities based on Mid Price adjustments
            foreach (var symbol in allSymbols)
            {
                var priceTick = _marketFeed.GetLatestPrice(symbol);
                if (priceTick == null) continue;

                decimal targetWeight = targetWeights.TryGetValue(symbol, out var tw) ? tw : 0.0m;
                decimal currentQty = portfolio.Positions.TryGetValue(symbol, out var pos) ? pos.TotalQuantity : 0.0m;

                decimal targetValue = investableCapital * targetWeight;

                // Route optimization bids/asks safely based on buy/sell requirements
                decimal price = currentQty * priceTick.Ask > targetValue ? priceTick.Bid : priceTick.Ask;

                if (price <= 0) continue;

                decimal targetQty = targetValue / price;
                decimal deltaQty = targetQty - currentQty;

                if (Math.Abs(deltaQty) <= 0.0001m) continue;

                decimal estimatedTradeValue = Math.Abs(deltaQty) * price;

                // Strip out tiny trades that do not meet minimum parameters
                if (estimatedTradeValue >= parameters.MinOrderValue)
                {
                    if (deltaQty > 0)
                    {
                        proposedTrades.Add(new TradeProposal(symbol, OrderSide.Buy, deltaQty, priceTick.Ask));
                    }
                    else
                    {
                        proposedTrades.Add(new TradeProposal(symbol, OrderSide.Sell, Math.Abs(deltaQty), priceTick.Bid));
                    }
                }
            }

            // Calculate hypothetical ending drift
            decimal aggregateDriftAfter = CalculateProjectedDrift(portfolio, targetWeights, proposedTrades, totalPortfolioValue);

            return new RebalancingProposal(proposedTrades, true, aggregateDriftBefore, aggregateDriftAfter);
        }

        private decimal CalculateProjectedDrift(
            Portfolio portfolio, 
            IReadOnlyDictionary<string, decimal> targetWeights, 
            List<TradeProposal> trades, 
            decimal totalValue)
        {
            var projectedQuantities = portfolio.Positions.ToDictionary(
                kvp => kvp.Key, 
                kvp => kvp.Value.TotalQuantity, 
                StringComparer.OrdinalIgnoreCase
            );

            foreach (var trade in trades)
            {
                if (!projectedQuantities.ContainsKey(trade.Symbol))
                {
                    projectedQuantities[trade.Symbol] = 0.0m;
                }

                if (trade.Side == OrderSide.Buy)
                {
                    projectedQuantities[trade.Symbol] += trade.Quantity;
                }
                else
                {
                    projectedQuantities[trade.Symbol] -= trade.Quantity;
                }
            }

            decimal aggregateDrift = 0.0m;
            foreach (var kvp in targetWeights)
            {
                var priceTick = _marketFeed.GetLatestPrice(kvp.Key);
                decimal price = priceTick != null ? (priceTick.Bid + priceTick.Ask) / 2.0m : 0.0m;

                projectedQuantities.TryGetValue(kvp.Key, out decimal finalQty);
                decimal finalValue = finalQty * price;
                decimal finalWeight = finalValue / totalValue;

                aggregateDrift += Math.Abs(finalWeight - kvp.Value);
            }

            return aggregateDrift;
        }
    }

    #endregion

    #region (3) TRADE EXECUTION SUBSYSTEM

    public record ExecutionOrder(
        string OrderId, 
        string Symbol, 
        OrderSide Side, 
        decimal Quantity, 
        decimal TargetPrice,
        DateTime CreatedAt
    )
    {
        public OrderStatus Status { get; set; } = OrderStatus.Pending;
        public decimal FilledQuantity { get; set; }
        public decimal ExecutionPrice { get; set; }
        public string ErrorMessage { get; set; } = string.Empty;
    }

    public interface IBrokerGateway
    {
        Task<ExecutionOrder> SubmitOrderAsync(ExecutionOrder order, CancellationToken cancellationToken);
    }

    /// <summary>
    /// Simulates a modern high-latency, multi-account broker connectivity framework 
    /// containing slippage, partial fills, and flat/variable clearing fees.
    /// </summary>
    public class SimulatedBrokerGateway : IBrokerGateway
    {
        private readonly Random _random = new();
        private readonly decimal _slippageVariance = 0.0005m; // 0.05% typical slippage

        public async Task<ExecutionOrder> SubmitOrderAsync(ExecutionOrder order, CancellationToken cancellationToken)
        {
            // Simulate broker network latency (50-250ms)
            await Task.Delay(_random.Next(50, 250), cancellationToken);

            // Add simulated execution slippage: 
            // Buy orders execute slightly higher than target, Sell orders slightly lower
            decimal slippagePercent = (decimal)(_random.NextDouble() * (double)_slippageVariance);
            decimal finalPrice = order.Side == OrderSide.Buy 
                ? order.TargetPrice * (1.0m + slippagePercent)
                : order.TargetPrice * (1.0m - slippagePercent);

            return order with
            {
                Status = OrderStatus.Filled,
                FilledQuantity = order.Quantity,
                ExecutionPrice = Math.Round(finalPrice, 4)
            };
        }
    }

    public interface ITradeExecutionEngine
    {
        Task ExecuteProposalAsync(
            Portfolio portfolio, 
            RebalancingProposal proposal, 
            TaxLotMethod taxLotMethod, 
            OptimizationParameters parameters,
            CancellationToken cancellationToken
        );
    }

    /// <summary>
    /// Execution Engine enforcing the "Sell-First" rule to unlock liquidity,
    /// dynamic order allocation sizing to protect cash thresholds, and exact Tax-Lot accounting rules.
    /// </summary>
    public class TradeExecutionEngine : ITradeExecutionEngine
    {
        private readonly IBrokerGateway _brokerGateway;

        public TradeExecutionEngine(IBrokerGateway brokerGateway)
        {
            _brokerGateway = brokerGateway;
        }

        public async Task ExecuteProposalAsync(
            Portfolio portfolio, 
            RebalancingProposal proposal, 
            TaxLotMethod taxLotMethod, 
            OptimizationParameters parameters,
            CancellationToken cancellationToken)
        {
            if (!proposal.Triggered || !proposal.Trades.Any()) return;

            // Split into Sells and Buys to execute the "Sell-First" rule.
            // This frees up required liquidity and guarantees clear compliance with trading margin limits.
            var sells = proposal.Trades.Where(t => t.Side == OrderSide.Sell).ToList();
            var buys = proposal.Trades.Where(t => t.Side == OrderSide.Buy).ToList();

            // 1. Process Sells
            foreach (var sellProposal in sells)
            {
                var order = new ExecutionOrder(
                    Guid.NewGuid().ToString("N"),
                    sellProposal.Symbol,
                    OrderSide.Sell,
                    sellProposal.Quantity,
                    sellProposal.EstimatedPrice,
                    DateTime.UtcNow
                );

                var execution = await _brokerGateway.SubmitOrderAsync(order, cancellationToken);
                if (execution.Status == OrderStatus.Filled)
                {
                    decimal volume = execution.FilledQuantity * execution.ExecutionPrice;
                    decimal commission = parameters.TransactionFeeFlat + (volume * parameters.TransactionFeeRate);
                    decimal netProceeds = volume - commission;

                    portfolio.UpdatePosition(execution.Symbol, pos =>
                    {
                        pos.RelieveLots(execution.FilledQuantity, taxLotMethod);
                    });

                    portfolio.Cash += netProceeds;
                    Console.WriteLine($"[TRADE] SOLD {execution.FilledQuantity} {execution.Symbol} @ ${execution.ExecutionPrice:F2}. Realized Net proceeds: ${netProceeds:F2} (Fee: ${commission:F2}).");
                }
            }

            // 2. Process Buys (Dynamic checking for cash constraints)
            foreach (var buyProposal in buys)
            {
                var orderValue = buyProposal.Quantity * buyProposal.EstimatedPrice;
                var estimatedCommission = parameters.TransactionFeeFlat + (orderValue * parameters.TransactionFeeRate);
                var totalEstimatedCost = orderValue + estimatedCommission;

                decimal availableCash = portfolio.Cash - parameters.CashReserve;

                if (availableCash <= 0)
                {
                    Console.WriteLine($"[WARN] Order of {buyProposal.Symbol} skipped: Insufficient cash reserve buffer available.");
                    continue;
                }

                decimal purchaseQuantity = buyProposal.Quantity;

                // Cash preservation check: Scale down order quantity if execution slippage risks overdrawing capital
                if (totalEstimatedCost > availableCash)
                {
                    decimal scaleRatio = availableCash / totalEstimatedCost;
                    purchaseQuantity = Math.Floor(buyProposal.Quantity * scaleRatio * 10000) / 10000; // Truncate safely

                    if (purchaseQuantity * buyProposal.EstimatedPrice < parameters.MinOrderValue)
                    {
                        Console.WriteLine($"[WARN] Skipped {buyProposal.Symbol} purchase. Scaled buy quantity too small to satisfy transaction parameters.");
                        continue;
                    }
                    Console.WriteLine($"[SCALING] Scaled down purchase of {buyProposal.Symbol} from {buyProposal.Quantity} to {purchaseQuantity} to preserve capital threshold constraints.");
                }

                var order = new ExecutionOrder(
                    Guid.NewGuid().ToString("N"),
                    buyProposal.Symbol,
                    OrderSide.Buy,
                    purchaseQuantity,
                    buyProposal.EstimatedPrice,
                    DateTime.UtcNow
                );

                var execution = await _brokerGateway.SubmitOrderAsync(order, cancellationToken);
                if (execution.Status == OrderStatus.Filled)
                {
                    decimal volume = execution.FilledQuantity * execution.ExecutionPrice;
                    decimal commission = parameters.TransactionFeeFlat + (volume * parameters.TransactionFeeRate);
                    decimal totalCost = volume + commission;

                    portfolio.UpdatePosition(execution.Symbol, pos =>
                    {
                        pos.AddTaxLot(new TaxLot(DateTime.UtcNow, execution.FilledQuantity, execution.ExecutionPrice));
                    });

                    portfolio.Cash -= totalCost;
                    Console.WriteLine($"[TRADE] BOUGHT {execution.FilledQuantity} {execution.Symbol} @ ${execution.ExecutionPrice:F2}. Invested Cost: ${totalCost:F2} (Fee: ${commission:F2}).");
                }
            }
        }
    }

    #endregion

    #region SYSTEM COORDINATION & LIVE INTEGRATION TEST

    public class Program
    {
        public static async Task Main(string[] args)
        {
            Console.WriteLine("==========================================================================");
            Console.WriteLine("        STARTING MODULAR AUTOMATED PORTFOLIO REBALANCING ENGINE           ");
            Console.WriteLine("==========================================================================");

            using var cts = new CancellationTokenSource();

            // 1. Initialize Subsystems
            var marketFeed = new MarketDataFeed();
            var optimizer = new PortfolioOptimizer(marketFeed);
            var broker = new SimulatedBrokerGateway();
            var executionEngine = new TradeExecutionEngine(broker);

            // Start Market Data Stream Ingestion
            marketFeed.StartStreaming(cts.Token);

            // Establish Simulated Market Baseline Quotes
            await marketFeed.EnqueueTickAsync(new MarketTick("AAPL", 150.00m, 150.10m, DateTime.UtcNow));
            await marketFeed.EnqueueTickAsync(new MarketTick("MSFT", 300.00m, 300.20m, DateTime.UtcNow));
            await marketFeed.EnqueueTickAsync(new MarketTick("GOOG", 2500.00m, 2500.50m, DateTime.UtcNow));
            await marketFeed.EnqueueTickAsync(new MarketTick("CASH", 1.00m, 1.00m, DateTime.UtcNow));

            // Wait brief moment for background tick consumption
            await Task.Delay(100);

            // 2. Setup Initial Portfolio State
            // Total Starting Portfolio Value = $10,000 Cash + (40 AAPL * $150 = $6,000) + (10 MSFT * $300 = $3,000) = $19,000
            var myPortfolio = new Portfolio("PORTFOLIO_ALPHA", 10000.00m);

            myPortfolio.UpdatePosition("AAPL", pos => {
                pos.AddTaxLot(new TaxLot(DateTime.UtcNow.AddDays(-60), 20m, 140.00m)); // Lot 1
                pos.AddTaxLot(new TaxLot(DateTime.UtcNow.AddDays(-30), 20m, 148.00m)); // Lot 2
            });

            myPortfolio.UpdatePosition("MSFT", pos => {
                pos.AddTaxLot(new TaxLot(DateTime.UtcNow.AddDays(-10), 10m, 290.00m));
            });

            Console.WriteLine($"Initial Portfolio Cash: ${myPortfolio.Cash:N2}");
            Console.WriteLine($"Initial Portfolio Valuation: ${myPortfolio.CalculateTotalValue(marketFeed):N2}\n");

            // Define Target Strategic Asset Allocations: AAPL: 35%, MSFT: 45%, GOOG: 20%
            var strategicAllocation = new TargetAllocation(new Dictionary<string, decimal>
            {
                { "AAPL", 0.35m },
                { "MSFT", 0.45m },
                { "GOOG", 0.20m }
            });

            // Rebalancing Constraint Settings
            var rebalancingParams = new OptimizationParameters(
                DriftThreshold: 0.02m,        // 2% Drift Threshold
                TransactionFeeFlat: 1.00m,    // $1.00 Broker Flat Clearing Fee
                TransactionFeeRate: 0.0005m,  // 0.05% Variable Broker Execution Fee
                MinOrderValue: 100.00m,       // $100 Minimum Threshold to trigger any order placement
                CashReserve: 500.00m          // Preserve $500 as cash buffer inside account
            );

            // 3. Execute First Rebalancing Loop Evaluation
            Console.WriteLine("--------------------------------------------------");
            Console.WriteLine("[ENGINE] Evaluation Cycle 1: Running Optimizer...");
            Console.WriteLine("--------------------------------------------------");

            var proposal = optimizer.ComputeRebalancing(myPortfolio, strategicAllocation, rebalancingParams);

            Console.WriteLine($"Drift Threshold Exceeded: {proposal.Triggered}");
            Console.WriteLine($"Aggregate Portfolio Weight Drift (Before): {proposal.AggregateDriftBefore:P2}");
            Console.WriteLine($"Projected Portfolio Weight Drift (After):  {proposal.AggregateDriftAfter:P2}");
            Console.WriteLine($"Trades Recommended: {proposal.Trades.Count}");

            foreach (var trade in proposal.Trades)
            {
                Console.WriteLine($" - Proposal: {trade.Side} {trade.Quantity:F4} shares of {trade.Symbol} (est price: ${trade.EstimatedPrice})");
            }

            if (proposal.Triggered)
            {
                Console.WriteLine("\nExecuting Portfolio trades sequentially (HIFO Basis)...");
                await executionEngine.ExecuteProposalAsync(myPortfolio, proposal, TaxLotMethod.HIFO, rebalancingParams, cts.Token);
            }

            // Post-Trade Run Status Check
            Console.WriteLine("\n--------------------------------------------------");
            Console.WriteLine("[ENGINE] Post-Trade Reconciliation Results:");
            Console.WriteLine("--------------------------------------------------");
            Console.WriteLine($"Reconciled Portfolio Cash: ${myPortfolio.Cash:N2}");

            foreach (var pos in myPortfolio.Positions.Values)
            {
                Console.WriteLine($"Position {pos.Symbol}: {pos.TotalQuantity:F4} shares total across {pos.GetTaxLots().Count} tax lots.");
                foreach (var lot in pos.GetTaxLots())
                {
                    Console.WriteLine($"   * Lot: {lot.Quantity} units bought @ ${lot.PricePerShare} (Acquired: {lot.AcquiredAt:yyyy-MM-dd})");
                }
            }
            Console.WriteLine($"Ending Total Valuation: ${myPortfolio.CalculateTotalValue(marketFeed):N2}");

            // Clean shutdown
            cts.Cancel();
            Console.WriteLine("==========================================================================");
            Console.WriteLine("                  REBALANCING WORKFLOW COMPLETED                          ");
            Console.WriteLine("==========================================================================");
        }
    }

    #endregion
}
```

